public class Jsoup_isValid_TriageGen2Test {









    @Test
    public void testIsValid_WithDisallowedAttributes() {
        String html = "<p style='color:red;'>Text</p>";
        // Basic whitelist does not allow 'style' attribute by default
        Whitelist whitelist = Whitelist.basic();
        assertFalse("Should be invalid when disallowed attributes are present", Jsoup.isValid(html, whitelist));
    }








}

